        if depth == target_len:
            if start in adj[u]:
                return True
            return False
        if depth > target_len:
            return False
        for v in adj[u]:
            if v != p and v not in visited:
                visited.add(v)
                if dfs(v, u, depth+1, start, target_len):
                    return True
                visited.remove(v)
        return False

    for start in range(n):
        visited = {start}
        if dfs(start, -1, 1, start, L):
            return True
    return False

def girth(edges):
    for L in range(3, n+1):
        if has_cycle_of_length(edges, L):
            return L
    return n+1

def is_3_colorable(edges):
    adj = {i: set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

