import random

n = 18

def has_cycle_of_length(edges, L, adj=None):
    if adj is None:
        adj = {i: set() for i in range(n)}
        for u,v in edges:
            adj[u].add(v)
            adj[v].add(u)

    def dfs(u, p, depth, start, target_len):
        if depth == target_len:
            if start in adj[u]:
                return True
            return False
        if depth > target_len:
            return False
        for v in adj[u]:
            if v != p and v not in visited:
                visited.add(v)
                if dfs(v, u, depth+1, start, target_len):
                    return True
                visited.remove(v)
        return False

    for start in range(n):
        visited = {start}
        if dfs(start, -1, 1, start, L):
            return True
    return False

def min_cycle_length(edges, adj=None):
    if adj is None:
        adj = {i: set() for i in range(n)}
        for u,v in edges:
            adj[u].add(v)
            adj[v].add(u)
    for L in range(3, n+1):
        if has_cycle_of_length(edges, L, adj):
            return L
    return n+1

def shortest_path_length(adj, start, end, max_len):
    """BFS to find shortest path length, up to max_len"""
    from collections import deque
    q = deque([(start, 0)])
    visited = {start}
    while q:
        v, d = q.popleft()
        if v == end:
            return d
        if d >= max_len:
            continue
        for u in adj[v]:
            if u not in visited:
                visited.add(u)
                q.append((u, d+1))
    return None

# Let's try to build a graph incrementally
# Start with a tree that has long paths

def build_graph():
    adj = {i: set() for i in range(n)}
    edges = []

    # First, let's create a cycle of length 18 (this has girth 18)
    # Actually, a cycle of length 18 has girth 18, which is >= 8
    # But it only has 18 edges. We need at least 29.

    # Let's start with a cycle of length 18
    for i in range(n):
        u = i
        v = (i+1) % n
        adj[u].add(v)
        adj[v].add(u)
        edges.append((min(u,v), max(u,v)))

    print(f"Starting with cycle of length {n}, edges: {len(edges)}")

    # Now try to add chords
    possible_chords = [(i,j) for i in range(n) for j in range(i+1, n) 
                       if j != (i+1)%n and i != (j+1)%n and (i,j) not in edges and (j,i) not in edges]
    random.shuffle(possible_chords)

    added = 0
    for u,v in possible_chords:
        # Check if adding this edge creates a cycle of length < 8
        # The shortest cycle through (u,v) would be shortest_path(u,v) + 1
        sp = shortest_path_length(adj, u, v, 7)
        if sp is None or sp >= 7:  # sp >= 7 means cycle length >= 8
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))
            added += 1
            if len(edges) >= 29:
                break

    print(f"Added {added} chords, total edges: {len(edges)}")
    g = min_cycle_length(edges, adj)
    print(f"Girth: {g}")

    if g >= 8 and len(edges) >= 29:
        return edges
    return None

